/**
 * Validates metadata generated by the AI to ensure it meets quality standards.
 *
 * @param {Object} metadata - The metadata object to validate.
 * @param {string} originalFilename - The original filename for comparison checks.
 * @returns {boolean} True if the metadata passes all validation checks.
 */
const validateMetadata = (metadata, originalFilename) => {
  // Check if metadata is a valid object
  if (!metadata || typeof metadata !== "object") return false;

  // Validate title: must be descriptive and not a generic fallback
  if (
    !metadata.title ||
    metadata.title.startsWith("Image ") ||
    metadata.title === originalFilename ||
    metadata.title.length < 20 ||
    metadata.title.includes("image_") ||
    metadata.title.includes("filename")
  ) {
    console.warn(`Invalid title: "${metadata.title}"`);
    return false;
  }

  // Validate description: must be detailed and not a generic placeholder
  if (
    !metadata.description ||
    metadata.description.startsWith("Uploaded image file") ||
    metadata.description.length < 40 ||
    metadata.description.includes("image file") ||
    metadata.description.includes("upload")
  ) {
    console.warn(
      `Invalid description: "${metadata.description?.substring(0, 40)}..."`
    );
    return false;
  }

  // Validate keywords: must have enough unique, relevant keywords
  if (
    !Array.isArray(metadata.keywords) ||
    metadata.keywords.length < 10 ||
    (metadata.keywords.length <= 5 &&
      (metadata.keywords.includes("image") ||
        metadata.keywords.includes("upload") ||
        metadata.keywords.includes("photo")))
  ) {
    console.warn(
      `Invalid keywords: ${
        metadata.keywords ? JSON.stringify(metadata.keywords) : "none"
      }`
    );
    return false;
  }

  return true;
};

module.exports = { validateMetadata };
